function latestRun(){return state.data?.plan_runs?.[0]||null}function tasks(did){return latestRun()?.checks.filter(x=>x.dataset_id===did)||[]}function nodes(did){return state.draft.nodes.filter(x=>x.dataset_id===did)}function trackNodes(tid){return state.draft.nodes.filter(x=>x.track_id===tid)}function trackTasks(tid){const ids=new Set(trackNodes(tid).map(n=>n.node_id));return latestRun()?.checks.filter(x=>x.track_id===tid||(!x.track_id&&ids.has(x.node_id)))||[]}
