  element.ondragstart=e=>{if(e.target.closest('.pf-card-delete')){e.preventDefault();return}draggingNode={id:item.node_id,track:item.track_id};e.dataTransfer.setData('text/plain',item.node_id);e.dataTransfer.effectAllowed='copyMove';element.classList.add('node-dragging');document.body.classList.add('sorting-nodes')};
