function syncProgressTracks(root){
  const previous=new Map([...root.children].map(el=>[el.dataset.trackId,el]));
  state.draft.tracks.forEach(track=>{
    const next=progressBar(track,true),old=previous.get(track.track_id);previous.delete(track.track_id);
    if(!old){root.append(next);return}
    const line=old.querySelector('.rule-track'),nextLine=next.querySelector('.rule-track'),scroll=line.scrollLeft;
    if(state.runningPlan&&line.children.length===nextLine.children.length){
      old.className=next.className;old.querySelector('.track-header').replaceWith(next.querySelector('.track-header'));
      [...nextLine.children].forEach((item,index)=>{const existing=line.children[index];if(existing.className!==item.className||existing.textContent!==item.textContent)existing.replaceWith(item)})
    }else{old.replaceWith(next);root.append(next);nextLine.scrollLeft=scroll}
  });previous.forEach(el=>el.remove())
}
