async function createSource(){try{const r=await api('/api/sources','POST',{name:$('source-name').value,model_name:$('source-model').value,role:$('source-role').value,match:$('source-match').value});state.data.sources=r.sources;$('source-create').classList.add('hidden');renderSources();toast('数据源已创建，请选择文件夹并刷新')}catch(e){notice(e.message)}}
async function chooseSource(src,folder){const value=String(folder||'').trim();if(!value)return notice('请输入本机文件夹完整路径。');const buttons=[...document.querySelectorAll('.source-card button')];buttons.forEach(button=>button.disabled=true);try{state.data.refresh={status:'running',dataset_id:src.dataset_id};$('refresh-detail').textContent='正在连接文件夹…';const result=await api('/api/sources/connect','POST',{dataset_id:src.dataset_id,folder:value});state.data.sources=result.sources;renderSources();toast('已连接本地文件夹，正在读取最新文件');pollRefresh()}catch(e){state.data.refresh={status:'failed',error:e.message};notice(e.message)}finally{buttons.forEach(button=>button.disabled=state.data.refresh?.status==='running')}}async function refreshSource(did){try{await api('/api/sources/refresh','POST',{dataset_id:did});$('refresh-status').textContent='刷新中';$('refresh-status').className='badge running';$('refresh-detail').textContent='正在检查最新文件并比较内容指纹…';toast('已开始刷新');pollRefresh()}catch(e){notice(e.message)}}let sourcePollTimer=null,sourcePollBusy=false;
async function pollRefresh(){
 if(sourcePollBusy)return;clearTimeout(sourcePollTimer);sourcePollBusy=true;
 try{const r=await api('/api/sources/status'),v=r.refresh;state.data.refresh=v;
 $('refresh-status').textContent=statusText(v.status);$('refresh-status').className='badge '+v.status;
 const seconds=v.started_at?Math.max(0,Math.floor((Date.now()-Date.parse(v.started_at))/1000)):0;
 $('refresh-detail').textContent=v.status==='running'?`${v.phase||'准备读取'} · 已读取 ${fmt(v.row_count||0)} 行 · ${seconds} 秒${v.file?' · '+v.file:''}`:(v.error||v.message||'等待刷新');
 document.querySelectorAll('.source-card .source-actions button').forEach(b=>b.disabled=v.status==='running');
 if(v.status==='running')sourcePollTimer=setTimeout(pollRefresh,1000);
 else if(v.status==='completed'){await load(false);toast(v.message||'数据已刷新')}
 else if(v.status==='failed'){notice(v.error||'刷新失败，请重试')}
 }catch(e){notice('读取进度失败，正在重连：'+e.message);sourcePollTimer=setTimeout(pollRefresh,3000)}finally{sourcePollBusy=false}
}

