function decoratePlanWorkspace(){
  const layout=document.querySelector('.wb-layout'),nav=layout?.querySelector('.wb-nav'),main=layout?.querySelector('.wb-main');
  if(!layout||!nav||!main)return;
  layout.classList.add('wb-layout-v2','wb-stack-workspace');
  const node=currentNode(),track=node?state.draft.tracks.find(t=>t.track_id===node.track_id):state.draft.tracks.find(t=>t.track_id===state.activeTrackId);
  const rail=make('nav','wb-flow-rail');rail.setAttribute('aria-label','校验流程');
  rail.append(uiButton('∑  聚合 SQL',()=>selectPlanItem('shared'),'wb-flow-tab '+(planUI.view==='shared'?'active':'')));
  state.draft.tracks.forEach(t=>{
    const items=trackNodes(t.track_id),active=track?.track_id===t.track_id;
    const tab=uiButton('',()=>{state.activeTrackId=t.track_id;selectPlanItem(items[0]?.node_id||'track:'+t.track_id,t.track_id)},'wb-flow-tab '+(active?'active':''));
    tab.append(make('span','',t.name),make('small','',String(items.length)));rail.append(tab)
  });
  nav.remove();layout.prepend(rail);
  if(!node||!track)return;
  const items=trackNodes(track.track_id),activeIndex=items.findIndex(item=>item.node_id===node.node_id),stack=make('section','wb-editor-stack');
  stack.style.setProperty('--stack-count',String(Math.min(items.length-1,4)));
  const inactive=items.filter(item=>item.node_id!==node.node_id);
  const activate=item=>{
    const swap=()=>{if(planUI.view===item.node_id)return;planUI.view=item.node_id;state.activeTrackId=track.track_id;planUI.fields=false;renderPlan()};
    if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion:reduce)').matches)document.startViewTransition(swap);else swap()
  };
  const visible=inactive.slice(0,4).reverse();
  visible.forEach((item,reversedIndex)=>{
    const depth=visible.length-reversedIndex,originalIndex=items.findIndex(x=>x.node_id===item.node_id),offset=(reversedIndex-(visible.length-1)/2)*96;
    const back=make('article','wb-stack-back'+(item.enabled===false?' is-disabled':''));back.style.setProperty('--depth',String(depth));back.style.setProperty('--x',offset+'px');back.style.setProperty('--tilt',(offset/96*1.15)+'deg');back.style.setProperty('--scale',String(.92-depth*.012));back.style.setProperty('--z',String(9-depth));
    back.title='编辑 '+item.name;
    const previewHead=uiButton('',()=>activate(item),'wb-stack-preview-head'),identity=make('span','wb-stack-preview-title');identity.append(make('span','wb-stack-number',String(originalIndex+1).padStart(2,'0')),make('strong','',item.name));
    previewHead.setAttribute('aria-label',`${String(originalIndex+1).padStart(2,'0')} ${item.name}，点击编辑`);
    previewHead.append(identity,make('small','',item.enabled===false?'已停用':(item.check_mode==='compare'?`启用 · 校验金额${item.compare_op||'<'}${fmtMoney(item.compare_value)}`:'启用 · 容差 '+(item.tolerance||'0.001'))));
    const code=make('pre','wb-stack-code',item.detail_sql.split('\n').slice(0,5).join('\n'));
    back.append(previewHead,code);stack.append(back)
  });
  const position=make('div','wb-stack-position');position.append(make('span','',`节点 ${activeIndex+1} / ${items.length}`));
  const controls=make('div','wb-stack-controls'),previous=items[(activeIndex-1+items.length)%items.length],next=items[(activeIndex+1)%items.length];
  if(items.length>1){controls.append(uiButton('← 上一个',()=>selectPlanItem(previous.node_id,track.track_id),'text-button'),uiButton('下一个 →',()=>selectPlanItem(next.node_id,track.track_id),'text-button'))}
  position.append(controls);main.prepend(position);main.style.viewTransitionName='active-node-editor';stack.append(main);layout.append(stack)
}
