  input.oninput=()=>input.setCustomValidity('');input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();save.click()}};
  actions.append(cancel,save);dialog.append(head,input,actions);dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();requestAnimationFrame(()=>{input.focus();input.select()})
