let planSavePromise=null,planAutosaveTimer=null,planAutosaveFailedValue=null;
function schedulePlanSave(){
 clearTimeout(planAutosaveTimer);
 if(!state.draft||!dirtyPlan()||state.runningPlan||state.data?.accounting?.current?.status==='closed'||draftValue()===planAutosaveFailedValue)return;
 planAutosaveTimer=setTimeout(()=>savePlan(true),1200);
}
async function savePlan(automatic=false){
 clearTimeout(planAutosaveTimer);
 if(planSavePromise){const ok=await planSavePromise;if(!ok)return false;return dirtyPlan()?savePlan(automatic):true}
 if(!dirtyPlan())return true;
 const submitted=draftValue();planUI.saving=true;updateSaveState();
 planSavePromise=(async()=>{try{const payload=JSON.parse(submitted);payload.base_version=state.data.plan.version||0;const p=await api('/api/plan','POST',payload);state.data.plan=p;
 if(draftValue()===submitted){state.draft.nodes.forEach(n=>{const saved=p.nodes.find(x=>x.node_id===n.node_id);if(saved){for(const key of ['manual_pass_period','manual_pass_at']){if(key in saved)n[key]=saved[key];else delete n[key]}}});planUI.baseline=draftValue()}else planUI.baseline=submitted;
 planAutosaveFailedValue=null;if(!automatic)toast('方案已保存');return true;
 }catch(e){planAutosaveFailedValue=submitted;notice('保存失败：'+e.message);return false}
 finally{planUI.saving=false;updateSaveState()}})();
 const ok=await planSavePromise;planSavePromise=null;if(ok&&dirtyPlan()){if(!automatic)return savePlan(false);schedulePlanSave()}return ok;
}



