function appendManualConfirmation(root,task){
 const node=state.draft.nodes.find(n=>n.node_id===task.node_id),period=state.data.accounting?.current?.period;
 if(!node)return;const confirmed=!!period&&node.manual_pass_period===period;
 const bar=make('div','result-toolbar'),button=make('button','button '+(confirmed?'ghost':'primary'),confirmed?'撤销人工确认':'人工确认通过');
 button.disabled=state.runningPlan||state.data.accounting?.current?.status==='closed';
 button.onclick=async()=>{if(dirtyPlan())return toast('请先保存方案，再进行人工确认');button.disabled=true;try{
 const plan=await api('/api/plan/manual-confirm','POST',{node_id:task.node_id,confirmed:!confirmed});state.data.plan=plan;initDraft();planUI.baseline=draftValue();renderPlan();renderTaskDetail();toast(confirmed?'已撤销，下次正常检验':'已确认，本账期后续运行跳过此节点');
 }catch(e){notice(e.message)}finally{button.disabled=false}};
 bar.append(button);if(confirmed)bar.append(make('span','badge passed','本账期人工确认'));root.append(bar);
}
async function downloadSelectedDetails(task){
 const indexes=[...(task._selected||[])];if(!indexes.length)return toast('请先勾选聚合行');
 const groups=indexes.map(i=>Object.fromEntries(task.dimensions.map(n=>[n,task.rows[i][task.columns.indexOf(n)]])));
 try{const r=await fetch(`/api/plan-runs/${latestRun().id}/detail-export`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataset_id:task.dataset_id,node_id:task.node_id,groups})});if(!r.ok)throw new Error((await r.json()).error);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=`selected-detail-${task.node_id.slice(0,8)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notice(e.message)}
}

