 const error=make('p','notice hidden'),actions=make('div','dialog-actions'),cancel=make('button','button ghost','取消'),save=make('button','button primary','保存配置');cancel.type='button';cancel.onclick=()=>dialog.close();save.type='submit';actions.append(cancel,save);form.append(error,actions);
 form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('/api/sources/update','POST',{dataset_id:src.dataset_id,role:role.value,...Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.value]))});await load(false);dialog.close();toast('数据源配置已保存')}catch(e){error.textContent=e.message;error.classList.remove('hidden')}finally{save.disabled=false}};
