function clearNodeDrag(){draggingNode=null;suppressNodeClickUntil=Date.now()+350;document.body.classList.remove('sorting-nodes');document.querySelectorAll('.node-dragging,.node-drop-target').forEach(el=>el.classList.remove('node-dragging','node-drop-target'))}
function copyDraggedNode(trackId,beforeId){
 if(!draggingNode||state.runningPlan||state.data?.accounting?.current?.status==='closed')return;
 const source=state.draft.nodes.find(n=>n.node_id===draggingNode.id),target=state.draft.tracks.find(t=>t.track_id===trackId);
 if(!source||!target||source.track_id===trackId)return;
 const copy={node_id:crypto.randomUUID().replaceAll('-',''),track_id:trackId,dataset_id:target.dataset_id,name:source.name,detail_sql:source.detail_sql,tolerance:source.tolerance||'0.001',enabled:source.enabled!==false,check_mode:source.check_mode||'zero'};if(copy.check_mode==='compare'){copy.compare_op=source.compare_op||'>';copy.compare_value=source.compare_value??'';if(source.report_label)copy.report_label=source.report_label}
 const at=beforeId?state.draft.nodes.findIndex(n=>n.node_id===beforeId):-1;
 if(at>=0)state.draft.nodes.splice(at,0,copy);else{const last=state.draft.nodes.findLastIndex(n=>n.track_id===trackId);state.draft.nodes.splice(last<0?state.draft.nodes.length:last+1,0,copy)}
 clearNodeDrag();renderPlan();renderOverview();renderFlow();toast(`已复制到「${target.name}」，请检查目标主表字段并保存方案`);
}
function enableFlowCopyTarget(element,track){
 if(window.Sortable)return;
 element.addEventListener('dragover',e=>{if(!draggingNode||draggingNode.track===track.track_id||state.runningPlan||state.data?.accounting?.current?.status==='closed')return;e.preventDefault();e.dataTransfer.dropEffect='copy';element.classList.add('node-drop-target')});
 element.addEventListener('dragleave',e=>{if(!element.contains(e.relatedTarget))element.classList.remove('node-drop-target')});
 element.addEventListener('drop',e=>{if(!draggingNode||draggingNode.track===track.track_id)return;e.preventDefault();e.stopPropagation();copyDraggedNode(track.track_id)});
}
